CREATE OR REPLACE FUNCTION public.has_test_access(p_user_id uuid, p_test_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_is_premium BOOLEAN;
BEGIN
    -- Check if test is free
    SELECT is_premium INTO v_is_premium FROM public.tests WHERE id = p_test_id;
    IF v_is_premium IS FALSE THEN
        RETURN TRUE;
    END IF;

    -- If user is admin, allow access
    IF public.has_role(p_user_id, 'admin') THEN
        RETURN TRUE;
    END IF;

    -- If test is premium, user MUST have an active subscription
    RETURN public.has_active_subscription(p_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_question_topic_chapter()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.topic_id IS NOT NULL AND NEW.chapter_id IS NULL THEN
        NEW.chapter_id := NEW.topic_id;
    ELSIF NEW.chapter_id IS NOT NULL AND NEW.topic_id IS NULL THEN
        NEW.topic_id := NEW.chapter_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_student_role_security()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- If email is NOT admin@practicekoro.online, block super_admin permanently
    IF LOWER(COALESCE(NEW.email, '')) <> 'admin@practicekoro.online' THEN
        IF NEW.admin_role = 'super_admin' THEN
            RAISE EXCEPTION 'Security Policy Violation: Only admin@practicekoro.online can be Super Admin'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- If role is not admin (e.g. student), admin_role is forcefully kept NULL
    IF NEW.role <> 'admin' THEN
        NEW.admin_role := NULL;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_razorpay_order(p_plan_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID;
    v_plan RECORD;
    v_order_id TEXT;
    v_payment_id UUID;
    v_key_id TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: User authentication required' USING ERRCODE = '40100';
    END IF;

    -- Retrieve active plan from database
    SELECT * INTO v_plan
    FROM public.subscription_plans
    WHERE id = p_plan_id AND is_active = TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Subscription plan not found or inactive' USING ERRCODE = '40400';
    END IF;

    -- Retrieve public key_id from payment_gateways, or fallback to app_settings
    SELECT key_id INTO v_key_id
    FROM public.payment_gateways
    WHERE gateway = 'razorpay' AND is_active = TRUE;

    IF v_key_id IS NULL OR TRIM(v_key_id) = '' THEN
        SELECT trim(both '"' from value::text) INTO v_key_id
        FROM public.app_settings
        WHERE id = 'payment_gateway_razorpay_key_id';
    END IF;

    -- Generate unique internal payment reference
    v_order_id := 'pk_local_' || substr(md5(gen_random_uuid()::text || clock_timestamp()::text), 1, 16);

    -- Insert pending payment record
    INSERT INTO public.payments (
        user_id,
        plan_id,
        amount,
        currency,
        gateway,
        order_id,
        razorpay_order_id,
        status
    )
    VALUES (
        v_user_id,
        v_plan.id,
        v_plan.price,
        v_plan.currency,
        'razorpay',
        v_order_id,
        v_order_id,
        'pending'
    )
    RETURNING id INTO v_payment_id;

    RETURN jsonb_build_object(
        'order_id', v_order_id,
        'payment_id', v_payment_id,
        'plan_id', v_plan.id,
        'plan_title', v_plan.title,
        'amount', v_plan.price,
        'currency', v_plan.currency,
        'duration_days', v_plan.duration_days,
        'key_id', v_key_id,
        'is_real_razorpay_order', false
    );
END;
$function$
